query:
SELECT ?item ?prop ?st ?rank ?value ?at ?atPrec ?atCal ?start ?startPrec ?startCal ?end ?endPrec ?endCal WHERE {
  VALUES ?item { wd:Q12680 wd:Q157 wd:Q158749 wd:Q158768 wd:Q158772 wd:Q158838 wd:Q169502 wd:Q191974 wd:Q2038 wd:Q2042 wd:Q2105 wd:Q2124 wd:Q215778 wd:Q2185 wd:Q274540 wd:Q296064 wd:Q296076 wd:Q296083 wd:Q296673 wd:Q3052772 wd:Q309995 wd:Q315656 wd:Q329 wd:Q517 wd:Q5721 wd:Q5738 wd:Q7721 wd:Q7732 wd:Q7750 wd:Q7758 wd:Q7771 }
  VALUES (?prop ?p ?ps ?psv) { ("P39" p:P39 ps:P39 psv:P39) }
  ?item ?p ?st . ?st wikibase:rank ?rank ; ?ps ?value .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st ?psv [ wikibase:timeValue ?at ; wikibase:timePrecision ?atPrec ; wikibase:timeCalendarModel ?atCal ] . }
  OPTIONAL { ?st pqv:P580 [ wikibase:timeValue ?start ; wikibase:timePrecision ?startPrec ; wikibase:timeCalendarModel ?startCal ] . }
  OPTIONAL { ?st pqv:P582 [ wikibase:timeValue ?end ; wikibase:timePrecision ?endPrec ; wikibase:timeCalendarModel ?endCal ] . }
}
